const S={token:localStorage.getItem('welink_token')||'',user:null,config:{},policy:{},registrationEnabled:false,spaceUser:'me',tab:'messages',contactTab:'friends',conversations:[],friends:[],requests:[],groupRequests:[],contactGroups:[],messages:[],active:null,profile:null,search:'',historyMode:false,reply:null,drafts:{},ws:null,offline:false,cacheView:false,cacheSyncing:false,remote:null,remoteTimer:null,remoteLocal:null};
