function toast(msg){const n=document.createElement('div');n.className='toast';n.textContent=msg;$('#toasts').append(n);setTimeout(()=>n.remove(),3800)}
async function api(path,options={}){const token=S.token,server=S.config.server;const value=await Received.run(path,options,()=>{if(!path.startsWith('/local')&&(token!==S.token||server!==S.config.server))throw Object.assign(Error('登录账号已变化'),{name:'AbortError'});return apiNetwork(path,options,token)});if(!path.startsWith('/local')&&(token!==S.token||server!==S.config.server))throw Object.assign(Error('登录账号已变化'),{name:'AbortError'});return value}
async function apiNetwork(path,options={},requestToken=S.token){const headers={...options.headers};if(requestToken)headers.Authorization='Bearer '+requestToken;if(options.body&&!(options.body instanceof FormData)){headers['Content-Type']='application/json';options.body=JSON.stringify(options.body)};const r=await fetch(path,{...options,headers});if(requestToken!==S.token&&!path.startsWith('/local'))throw Object.assign(Error('登录账号已变化'),{name:'AbortError'});if(r.status===401&&S.user&&requestToken===S.token&&!path.startsWith('/local')){logout(false);throw Object.assign(Error('登录已过期，请重新登录'),{status:401})};if(!r.ok){let p;try{p=await r.json()}catch{}throw Object.assign(Error(p?.error||`请求失败 (${r.status})`),{status:r.status})};return r.status===204?null:r.json()}
const action=(p,body={})=>api(p,{method:'POST',body});
function shortTime(value){const d=new Date(value),today=new Date();if(d.toDateString()===today.toDateString())return d.toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'});const yesterday=new Date(Date.now()-86400000);if(d.toDateString()===yesterday.toDateString())return '昨天';return `${d.getMonth()+1}/${d.getDate()}`}
function fullTime(t){return new Date(t).toLocaleString('zh-CN',{month:'long',day:'numeric',hour:'2-digit',minute:'2-digit',hour12:false})}
function preview(m){if(!m)return '开始聊天';if(m.kind==='call'&&!m.recalled)return Calls.summary(m);if(m.kind==='forward'&&!m.recalled){try{return '[聊天记录] '+JSON.parse(m.text).title}catch{return '[聊天记录]'}}if(m.kind==='meeting'&&!m.recalled){try{return '[会议] '+JSON.parse(m.text).title}catch{return '[会议]'}}return m.recalled?'消息已撤回':m.kind==='voice'?'[语音]':m.kind==='video'?'[视频]':m.kind==='image'?'[图片]':m.kind==='file'?`[文件] ${m.fileName}`:m.text}
function modal(title,body,footer='',wide=false){window.WeLinkMediaBeforeModal?.();$('#overlays').innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><header class="modal-head"><h3>${esc(title)}</h3>${btn('close','关闭','close-modal')}</header><div class="modal-body">${body}<div class="form-error" id="modal-error"></div></div>${footer?`<footer class="modal-footer">${footer}</footer>`:''}</section></div>`;modalHandler=null;const dialog=$('.modal');setTimeout(()=>{if(dialog?.isConnected&&!dialog.contains(document.activeElement))dialog.querySelector('input:not([type=checkbox]):not([type=file]):not([type=range])')?.focus()},40)}
const modalError=e=>{$('#modal-error')?$('#modal-error').textContent=e.message:toast(e.message)};
