function renderAuth(register=false){if(register&&!S.registrationEnabled){toast('暂未开放自助注册，请联系管理员');register=false}const choices=register?cartoonChoices(8):[];QR.stop();S.user=null;Desktop.unread();$('#app').innerHTML=`<main class="auth-shell ${register?'registering':''}">${windows()}<form class="auth-card" id="auth-form">${logo()}<h2>${register?'创建 WeLink 账号':'欢迎回来'}</h2><p class="subtitle">${register?'新的相遇，从这里开始':'和在意的人，随时保持联系'}</p>${register?'<div class="register-avatars"><div class="cartoon-heading"><span>选一个喜欢的头像</span><button type="button" id="register-avatar-shuffle">换一批</button></div><input type="hidden" name="avatar" id="register-avatar" value="'+choices[0].id+'"><div class="cartoon-grid compact" id="register-avatar-options">'+cartoonOptions(choices,choices[0].id)+'</div></div>':''}<div class="auth-fields">${register?'<input name="name" autocomplete="nickname" placeholder="昵称" aria-label="昵称" maxlength="32" required>':''}<input name="account" autocomplete="username" placeholder="${register?'登录别名（可选）':'WeLink 号码 / 登录别名'}" aria-label="账号" minlength="5" maxlength="24" ${register?'':'required'}><input name="password" type="password" autocomplete="${register?'new-password':'current-password'}" placeholder="${register?'设置密码（至少 8 位）':'密码'}" aria-label="密码" minlength="8" maxlength="72" required></div><div class="auth-error" id="auth-error"></div><button type="submit" class="primary">${register?'注册并登录':'登录'}</button>${!register&&S.config.platform!=='android'?'<button type="button" class="qr-login-entry" data-action="qr-login">使用二维码登录</button>':''}<div class="auth-links">${register||S.registrationEnabled?`<button type="button" data-action="${register?'login':'register'}">${register?'已有账号，去登录':'注册账号'}</button>`:''}<button type="button" data-action="connection">连接设置</button></div><p class="auth-consent">WeLink 独立账号 · 密码加密保存<br>登录后即可使用消息、文件与远程协助</p></form><small class="auth-footer">WeLink 0.1.0 · 让沟通更近一步</small></main>`;if(register){$('#register-avatar-shuffle').onclick=()=>{const next=cartoonChoices(8);$('#register-avatar').value=next[0].id;$('#register-avatar-options').innerHTML=cartoonOptions(next,next[0].id)};$('#register-avatar-options').onclick=e=>{const b=e.target.closest('[data-cartoon]');if(b){$('#register-avatar').value=b.dataset.cartoon;$('#register-avatar-options').querySelectorAll('[data-cartoon]').forEach(n=>{n.classList.toggle('selected',n===b);n.setAttribute('aria-checked',String(n===b))})}}};$('#auth-form').onsubmit=async e=>{e.preventDefault();const submit=$('button[type=submit]',e.target);submit.disabled=true;$('#auth-error').textContent='';try{const p=[...new FormData(e.target)].reduce((p,[k,v])=>(p[k]=v,p),{});const result=await action('/api/auth/'+(register?'register':'login'),p);S.token=result.token;localStorage.setItem('welink_token',S.token);S.user=result.user;await enter();if(register)modal('注册成功',`<p class="hint">请记住你的 WeLink 号码，可用于登录和搜索用户。</p><div class="welink-number">${esc(S.user.number)}</div>`,'<button class="primary" data-action="close-modal">开始使用</button>')}catch(err){$('#auth-error').textContent=err.message;submit.disabled=false}}}
function nav(){const unread=S.conversations.reduce((n,c)=>n+(c.muted?(c.mentionCount||0):c.unread),0),requests=S.requests.filter(q=>q.recipient===S.user.id&&q.status==='pending').length+S.groupRequests.filter(q=>q.canReview&&q.status==='pending').length;return `<aside class="rail"><button class="self" title="个人资料" data-action="profile">${av(S.user,'',true)}</button><nav>${[['messages','chat','消息',unread],['contacts','contacts','联系人',requests],['meetings','video','会议',0],['remote','monitor','远程协助',0],['drive','cloud','网盘',0],['space','notebook','空间',0],['files','folder','文件',0],['favorites','star','收藏',0],['profile','user','我的',0]].map(([tab,i,t,n])=>`<button data-nav="${tab}" class="${S.tab===tab?'active':''}" title="${t}" aria-label="${t}">${icon(i)}<span class="rail-label">${t==='远程协助'?'远程':t}</span>${n?`<span class="badge">${n>99?'99+':n}</span>`:''}</button>`).join('')}</nav><div class="rail-bottom">${btn('settings','设置','settings')}${btn('more','更多','more-menu')}</div></aside>`}
function renderShell(){const utility=!['messages','contacts'].includes(S.tab);$('#app').innerHTML=`<div class="shell ${S.active&&S.tab==='messages'?'in-chat':''} ${utility?'in-utility':''}">${nav()}<aside class="sidebar"><div class="mobile-title"><button data-action="profile">${av(S.user)}</button><h2>${S.tab==='contacts'?'联系人':'消息'}</h2>${btn('plus','查找用户或创建群聊','add-menu')}</div><div class="searchbar"><label class="searchbox">${icon('search')}<input id="sidebar-search" value="${esc(S.search)}" placeholder="搜索" aria-label="搜索会话或联系人"></label>${btn('plus','查找用户或创建群聊','add-menu')}</div><div class="sidebar-connection-status"></div><div id="sidebar-content" class="list-scroll"></div></aside><main class="main">${windows()}<div id="connection-status"></div><div id="main-content" style="display:contents"></div></main></div>`;renderSidebar();renderMain();$('#sidebar-search').oninput=e=>{S.search=e.target.value;renderSidebar()};connectionState()}
function renderSidebar(){const list=$('#sidebar-content');if(!list)return;const q=S.search.toLowerCase();if(S.tab==='contacts'){list.innerHTML='<button class="notify-row group-notice-row" data-group="requests">'+icon('contacts')+'群通知</button><div class="contact-tab"><button data-contact-tab="friends" class="'+(S.contactTab==='friends'?'active':'')+'">联系人</button><button data-contact-tab="groups" class="'+(S.contactTab==='groups'?'active':'')+'">群聊</button></div>'+(S.contactTab==='friends'?Contacts.sidebar():S.conversations.filter(c=>c.kind==='group'&&(c.name+(c.group?.number||'')).toLowerCase().includes(q)).map(conversationRow).join('')||'<div class="empty-list">还没有群聊</div>');return}const result=S.conversations.filter(c=>(c.name+(c.peer?.number||'')+(c.group?.number||'')+(c.last?.text||'')).toLowerCase().includes(q));const users=q?S.friends.filter(u=>(u.name+(u.remark||'')+u.number+u.id+u.account).toLowerCase().includes(q)):[];list.innerHTML=result.map(conversationRow).join('')+(users.length?'<div class="search-section-label">搜索用户 · 直接聊天</div>'+users.map(u=>'<div class="user-search-result"><button class="conversation-row" data-start-chat="'+u.id+'">'+av(u,'',true)+'<div class="row-text"><div class="row-title"><b>'+esc(u.remark||u.name)+'</b></div><div class="row-preview">'+esc(u.number)+'</div></div></button><div class="user-search-actions"><button data-start-chat="'+u.id+'">发消息</button><button data-user-call="'+u.id+'" data-user-call-mode="audio" title="语音通话" aria-label="语音通话">'+icon('phone')+'</button><button data-user-call="'+u.id+'" data-user-call-mode="video" title="视频通话" aria-label="视频通话">'+icon('video')+'</button></div></div>').join(''):'')+(!result.length&&!users.length?'<div class="empty-list">'+(q?'没有找到相关用户或会话':'暂无消息<br>搜索用户，直接开始聊天')+'</div>':'')+'<button class="search-action" data-action="add-friend">查找用户</button>'}

function conversationRow(c){return `<button class="conversation-row ${S.active===c.id?'selected':''} ${c.pinned?'pinned':''}" data-conversation="${c.id}">${av(c.kind==='group'?{name:c.name,kind:'group',avatar:c.avatar||'group'}:c.peer||c)}<div class="row-text"><div class="row-title"><b>${esc(c.name)}</b>${c.kind==='direct'?Contacts.badge(c.peer):''}<time>${c.last?shortTime(c.last.created):''}</time></div><div class="row-preview"><span>${c.mentionCount?'<i class="mention-unread">[有人@我]</i>':''}${esc(c.kind==='group'&&c.last&&!c.last.recalled?`${c.last.name}：`:'')}${esc(preview(c.last))}</span>${c.muted?icon('mute'):''}${c.unread?`<i class="badge">${c.unread>99?'99+':c.unread}</i>`:''}</div></div></button>`}
function activeConversation(){return S.conversations.find(c=>c.id===S.active)}
function renderMain(){const main=$('#main-content');if(!main)return;if(S.tab==='drive'){Cloud.renderDrive().catch(e=>toast(e.message));return}if(S.tab==='space'){Cloud.renderSpace(S.spaceUser||'me').catch(e=>{main.innerHTML=empty('空间',e.message)});return}if(S.tab==='admin'){Admin.render().catch(e=>toast(e.message));return}if(S.tab==='contacts'){if(S.profile){renderContactProfile();return};main.innerHTML=empty('联系人','找到好友，让联系更简单');return};if(S.tab==='files'){renderFiles();return};if(S.tab==='favorites'){renderFavorites();return};if(S.tab==='meetings'){Meetings.renderHome();return};if(S.tab==='remote'){renderRemoteHome();return};if(S.tab==='profile'){renderMyPage();return};const c=activeConversation();if(!c){main.innerHTML=empty('WeLink','每一句，都有回应。',true);return};main.innerHTML=`<header class="chat-head">${btn('back','返回','back','').replace('class="icon-btn"','class="icon-btn mobile-back"')}<h2>${esc(c.name)}<small id="typing-status">${c.kind==='direct'?(c.peer?.online?'在线':'离线'):'群聊'}</small></h2><div class="chat-actions">${c.kind==='direct'?'<button class="icon-btn" title="语音通话" aria-label="语音通话" data-call-mode="audio">'+icon('phone')+'</button><button class="icon-btn" title="视频通话" aria-label="视频通话" data-call-mode="video">'+icon('video')+'</button>':btn('phone','语音通话','meeting-audio-call')+btn('video','发起会议','meeting-start')}${btn('monitor','远程协助','remote')}${btn('search','搜索聊天记录','search-history')}${btn('more','聊天设置','chat-detail')}</div></header><div id="sharing-banner"></div><div id="mention-jump"></div><section class="message-area" id="messages" aria-label="聊天记录"></section><section class="composer" aria-label="消息输入"><div class="reply-draft hidden" id="reply-draft"></div><div class="compose-tools">${Media.tools()}${Mentions.tool()}${btn('emoji','表情','emoji')}${btn('image','发送图片','image')}<button class="icon-btn" title="发送视频" aria-label="发送视频" data-media="video">${icon('video')}</button>${btn('folder','发送文件','file')}${btn('scissors','截图','screenshot')}${btn('monitor','远程协助','remote')}<span class="spacer"></span><button class="history-btn" data-action="search-history">${icon('history')}聊天记录</button></div><textarea id="composer" placeholder="" aria-label="输入消息" maxlength="6000">${esc(S.drafts[c.id]||'')}</textarea>${Media.input()}<div class="compose-bottom"><small>Enter 发送，Shift + Enter 换行</small><button class="send-btn" id="send-message" data-action="send" ${S.drafts[c.id]?.trim()?'':'disabled'}>发送</button></div><input type="file" id="image-input" class="file-input" accept="image/png,image/jpeg,image/gif,image/webp"><input type="file" id="file-input" class="file-input"></section>`;renderMessages();const input=$('#composer');input.oninput=()=>{Mentions.changed();S.drafts[S.active]=input.value;Outbox.saveDraft().catch(()=>{});$('#send-message').disabled=!input.value.trim();if(Date.now()-typingAt>2500&&S.ws?.readyState===1){typingAt=Date.now();S.ws.send(JSON.stringify({type:'typing',conversationId:S.active}))}};input.onkeydown=e=>{if(Mentions.key(e))return;if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();sendMessage()}};input.onpaste=e=>{const f=[...(e.clipboardData?.files||[])][0];if(f){e.preventDefault();upload(f)}};$('#image-input').onchange=e=>{if(e.target.files[0])upload(e.target.files[0]);e.target.value=''};$('#file-input').onchange=e=>{if(e.target.files[0])upload(e.target.files[0]);e.target.value=''};const area=$('#messages');renderReply();renderSharing();Media.mount();Groups.syncComposer();Contacts.syncComposer();Mentions.mount()}
function empty(title,sub,add=false){return `<div class="empty-chat"><img src="/assets/icon.svg" alt=""><h2>${title}</h2><p>${sub}</p>${add?'<button class="primary" data-action="add-friend">查找用户</button>':''}</div>`}
function fileURL(id){return '/api/files/'+encodeURIComponent(id)}
function messageHTML(m){if(m.recalled)return `<div class="recalled" data-message="${m.id}">${Forwarding.checkbox(m)}${m.sender===S.user.id?'你':esc(m.name)}撤回了一条消息</div>`;const mine=m.sender===S.user.id;const quote=S.messages.find(x=>x.id===m.replyId)||m.reply;let content=Mentions.text(m);if(m.kind==='call')content=Calls.card(m);if(m.kind==='voice'||m.kind==='video')content=Media.bubble(m);if(m.kind==='forward')content=Forwarding.card(m);if(m.kind==='meeting'){try{const meeting=JSON.parse(m.text);content=`<button class="file-card" data-meeting-code="${esc(meeting.code)}">${icon('video')}<span><b>${esc(meeting.title)}</b><small>会议号 ${esc(meeting.code)} · 点击加入</small></span></button>`}catch{}}if(m.kind==='image')content=S.offline?'<div class="file-card">'+icon('image')+'<span><b>'+esc(m.fileName||'图片')+'</b><small>联网后查看图片</small></span></div>':`<img src="${fileURL(m.attachmentId)}" alt="${esc(m.fileName||'图片')}" loading="lazy" data-preview-image="${m.attachmentId}">`;if(m.kind==='file')content=`<button class="file-card" data-download="${m.attachmentId}" data-filename="${esc(m.fileName)}">${icon('file')}<span><b>${esc(m.fileName)}</b><small>${bytes(m.fileSize)} · 点击下载</small></span></button>`;return `<article class="message ${mine?'mine':''}" data-message="${m.id}">${Forwarding.checkbox(m)}${av(m)}<div class="message-body">${activeConversation()?.kind==='group'&&!mine?`<span class="message-name">${esc(m.name)}</span>`:''}<div class="bubble ${m.kind==='image'?'image-bubble':m.kind==='forward'?'forward-bubble':m.kind==='voice'?'voice-bubble':m.kind==='video'?'video-bubble':''}">${content}</div>${m.replyId?`<button class="quote" data-action="jump-message" data-mid="${m.replyId}" title="查看原消息">${quote?esc(quote.name+'：'+preview(quote)):'原消息不可用'}</button>`:''}<span class="message-time">${shortTime(m.created)}</span></div><div class="message-menu"><button class="icon-btn" title="转发" aria-label="转发" data-fw="single" data-mid="${m.id}">${icon('send')}</button>${btn('reply','引用','quote',`data-mid="${m.id}"`)}${btn('star','收藏','favorite',`data-mid="${m.id}"`)}${mine&&Date.now()-m.created<120000?btn('history','撤回','recall',`data-mid="${m.id}"`):''}${btn('trash','删除','delete-message',`data-mid="${m.id}"`)}</div></article>`}
function renderMessages(keep=false){const area=$('#messages');if(!area)return;const old=area.scrollTop,near=area.scrollHeight-area.clientHeight-old<100;let last=0;area.innerHTML=(S.messages.length>=60?'<button class="load-more" data-action="load-older">查看更多消息</button>':'')+S.messages.map(m=>{let date='';if(m.created-last>300000){last=m.created;date=`<div class="timestamp">${fullTime(m.created)}</div>`}return date+messageHTML(m)}).join('');if(S.historyMode)area.insertAdjacentHTML('beforeend','<div class="history-live-bar"><button data-action="load-newer">查看后续消息</button><button data-action="latest-messages">返回最新消息</button></div>');const pending=(Outbox.html(S.active)+Transfers.html(S.active));if(!S.messages.length&&!pending)area.innerHTML='<div class="timestamp">'+(S.offline?'此会话尚无本机缓存，联网后加载消息':'和好友打个招呼吧')+'</div>';area.insertAdjacentHTML('beforeend',pending);Forwarding.sync();Media.sync();if(!keep||near)area.scrollTop=area.scrollHeight;else area.scrollTop=old;$$('img',area).forEach(img=>img.onload=()=>{if(!keep||near)area.scrollTop=area.scrollHeight})}
async function selectConversation(id){Mentions.select(id);Media.reset();Forwarding.reset(false);S.active=id;S.historyMode=false;S.tab='messages';S.reply=Outbox.replyPlaceholder(id);S.messages=[];S.profile=null;S.search='';renderShell();try{const m=await api(`/api/conversations/${id}/messages`);if(S.active!==id)return;S.messages=m;renderMessages();await Outbox.restoreReply(id);await markRead();if(innerWidth>700)$('#composer')?.focus()}catch(e){toast(e.message)}}
async function markRead(){if(S.offline||S.cacheSyncing)return;const last=S.messages[S.messages.length-1];if(!last||Desktop.hidden()||S.historyMode||S.tab!=='messages'||!$('#messages'))return;await action(`/api/conversations/${S.active}/read`,{seq:last.seq});const c=activeConversation();if(c){c.unread=0;c.mentionCount=0;c.firstMentionId=''}renderSidebar();updateRail()}
function updateRail(){const old=$('.rail');if(old)old.outerHTML=nav();Desktop.unread()}
async function sendMessage(){const input=$('#composer');if(!input?.value.trim()||input.disabled)return;const text=input.value,cid=S.active,owner=Outbox.scope();input.disabled=true;try{await Outbox.enqueue(cid,{kind:'text',text,mentions:Mentions.payload(),replyId:S.reply?.id||''},null,{},true);if(Outbox.scope()!==owner)return;if(S.active===cid&&input===$('#composer')){input.value='';$('#send-message').disabled=true;S.reply=null;renderReply();renderMessages()}}catch(e){Mentions.failed();toast(e.message)}finally{if(input.isConnected){input.disabled=false;input.focus();Groups.syncComposer();Contacts.syncComposer()}}}
function renderReply(){const d=$('#reply-draft');if(!d)return;d.classList.toggle('hidden',!S.reply);d.closest('.composer').classList.toggle('has-reply',!!S.reply);d.innerHTML=S.reply?`<span>回复 ${esc(S.reply.name)}：${esc(preview(S.reply))}</span>${btn('close','取消引用','cancel-reply')}`:''}
async function upload(file,forceFile=false,cid=S.active){if(cid===S.active&&!forceFile&&(/^video\//.test(file.type)||/\.(mp4|webm|m4v)$/i.test(file.name))){await Media.sendVideo(file);return}if(!cid)return;try{await Outbox.enqueue(cid,{kind:forceFile?'file':'auto',text:''},file)}catch(e){toast(e.message)}}
function bytes(n){return n>=1099511627776?(n/1099511627776).toFixed(1)+' TB':n>=1073741824?(n/1073741824).toFixed(1)+' GB':n>=1048576?(n/1048576).toFixed(1)+' MB':n>=1024?Math.ceil(n/1024)+' KB':n+' B'}
async function refresh(){if(!S.user)return;const userId=S.user.id;const [conversations,friends,requests,groupRequests,contactGroups]=await Promise.all([api('/api/conversations'),api('/api/friends'),api('/api/requests'),api('/api/group-requests'),api('/api/contact-groups')]);if(S.user?.id!==userId)return;S.conversations=conversations;S.friends=friends;S.requests=requests;S.groupRequests=groupRequests;S.contactGroups=contactGroups;if(S.profile){S.profile=friends.find(u=>u.id===S.profile.id)||null;if(S.tab==='contacts')renderMain()}if(S.active&&!conversations.some(c=>c.id===S.active)){Media.reset();Forwarding.reset(false);S.active=null;S.messages=[];S.reply=null;closeModal();renderShell();toast('会话列表已更新')}renderSidebar();updateRail();const c=activeConversation();if(c&&$('#typing-status'))$('#typing-status').textContent=c.kind==='direct'?(c.peer?.online?'在线':'离线'):'群聊';Groups.syncComposer();Contacts.syncComposer()}
function queueRefresh(){clearTimeout(refreshTimer);refreshTimer=setTimeout(()=>refresh().catch(e=>toast(e.message)),200)}
async function enter(){if(!S.cacheView)await Received.identified(S.user);S.policy=await api('/api/config');await refresh();await Outbox.start();renderShell();connectEvents();Calls.start()}
function connectEvents(){if(!S.user)return;S.ws?.close();const ws=new WebSocket(location.origin.replace(/^http/,'ws')+'/api/ws');S.ws=ws;ws.onopen=async()=>{if(S.ws!==ws||!S.user)return;S.cacheView=false;S.cacheSyncing=true;connectionState();try{await Received.reconcile(api);if(S.ws!==ws||!S.user)return;await refresh();if(S.active&&!S.historyMode){const cid=S.active,ms=await api('/api/conversations/'+cid+'/messages');if(S.ws!==ws||!S.user)return;if(S.active===cid&&!S.historyMode){S.messages=ms;renderMessages(true)}}if(S.ws===ws&&!S.cacheView){S.offline=false;Outbox.kick()}}catch{}finally{if(S.ws===ws){S.cacheSyncing=false;connectionState();markRead().catch(()=>{})}}};ws.onmessage=e=>{if(S.ws!==ws||!S.user||S.signingOut)return;let event;try{event=JSON.parse(e.data)}catch{return}const d=event.data;if(event.type==='call'){Calls.changed(d)}else if(event.type==='drive'||event.type==='space'){Cloud.changed(event.type)}else if(event.type==='call-history'){Calls.historyChanged()}else if(event.type==='message'){Received.event('message',d).catch(()=>{});Outbox.ack(d).catch(()=>{});if(S.active===d.conversationId&&!S.historyMode){if(!S.messages.some(m=>m.id===d.id))S.messages.push(d);renderMessages(true);markRead().catch(()=>{})}if((S.active!==d.conversationId||S.tab!=='messages'||Desktop.hidden())&&d.sender!==S.user.id&&(!S.conversations.find(c=>c.id===d.conversationId)?.muted||Mentions.applies(d))){if(!Desktop.native&&document.hidden&&window.Notification?.permission==='granted')new Notification(S.friends.find(u=>u.id===d.sender)?.remark||d.name,{body:(Mentions.applies(d)?'有人 @你：':'')+preview(d),icon:'/assets/icon.svg'});document.title=Mentions.applies(d)?'有人 @你 · WeLink':'新消息 · WeLink'}queueRefresh()}else if(event.type==='profile'){Avatars.changed(d);queueRefresh()}else if(event.type==='recall'){applyRecall(d)}else if(event.type==='message-deleted'){applyDeletion(d)}else if(event.type==='typing'){if(d.conversationId===S.active&&d.userId!==S.user.id&&$('#typing-status')){$('#typing-status').textContent='对方正在输入…';setTimeout(()=>{if($('#typing-status'))$('#typing-status').textContent=activeConversation()?.peer?.online?'在线':''},3200)}}else if(event.type==='meeting-invite'){Meetings.invited(d)}else if(event.type==='remote'){remoteEvent(d)}else{queueRefresh()}};ws.onclose=e=>{if(S.ws!==ws||!S.user||S.signingOut)return;if(e.code===4001){logout(false);toast('此设备已退出登录，请重新登录');return}S.offline=true;connectionState();setTimeout(async()=>{if(S.user&&S.ws===ws){try{await api('/api/me')}catch{}if(S.user&&S.ws===ws)connectEvents()}},2500)}}
function connectionState(){const text=S.cacheSyncing?'正在核对本机聊天记录…':S.cacheView?'离线查看 · 仅显示本机已缓存的记录':S.offline?'网络连接已断开，正在重新连接…':'';for(const n of [$('#connection-status'),$('.sidebar-connection-status')])if(n)n.innerHTML=text?'<div class="connection-state" role="status">'+text+'</div>':''}
async function logout(notify=true){if(S.signingOut)return;const signingOutToken=S.token;Media.reset();Forwarding.reset(false);S.signingOut=true;Calls.stop();Outbox.stop();Transfers.stop();Cloud.reset();Admin.reset();Avatars.reset();Mentions.reset();S.drafts={};try{Meetings.close();await Received.forget();if(notify)try{await action('/api/auth/logout')}catch{}S.user=null;const ws=S.ws;S.ws=null;ws?.close();S.token='';if(localStorage.getItem('welink_token')===signingOutToken)localStorage.removeItem('welink_token');S.active=null;S.messages=[];S.conversations=[];S.friends=[];S.offline=false;S.cacheView=false;S.cacheSyncing=false;closeModal();stopRemote(false).catch(()=>{});renderAuth()}finally{S.signingOut=false}}
function addFriend(){modal('查找用户',`<label for="find-user">WeLink 号码 / 昵称</label><input id="find-user" placeholder="输入 WeLink 号码或昵称" autocomplete="off"><div id="user-results" class="member-select"><p class="hint">输入至少两个字符，找到想联系的人。</p></div>`);$('#find-user').oninput=e=>{clearTimeout(searchTimer);const q=e.target.value;searchTimer=setTimeout(async()=>{try{const users=await api('/api/users?q='+encodeURIComponent(q));const list=$('#user-results');if(!list)return;list.innerHTML=users.map(u=>`<div class="utility-row">${av(u)}<div class="body"><b>${esc(u.name)}</b><p>${esc(u.number||u.account)}</p></div><button class="secondary" data-start-chat="${u.id}">发消息</button><button class="icon-btn" data-user-call="${u.id}" data-user-call-mode="audio" title="语音通话">${icon('phone')}</button><button class="icon-btn" data-user-call="${u.id}" data-user-call-mode="video" title="视频通话">${icon('video')}</button></div>`).join('')||'<div class="empty-list">未找到用户</div>'}catch(e){modalError(e)}},250)}}
function requestFriend(id,name){modal('添加 '+name,'<label for="request-message">验证消息</label><input id="request-message" maxlength="150" value="你好，我是 '+esc(S.user.name)+'">','<button class="secondary" data-action="close-modal">取消</button><button class="primary" data-action="modal-submit">发送申请</button>');modalHandler=async()=>{await action('/api/requests',{userId:id,message:$('#request-message').value});closeModal();toast('好友申请已发送');await refresh()}}
function createGroup(){modal('创建群聊',`<label for="group-name">群名称</label><input id="group-name" maxlength="60" placeholder="给群聊起个名字"><label>选择好友</label><div class="member-select">${S.friends.map(u=>`<label class="check-row">${av(u)}${esc(u.name)}<input type="checkbox" value="${u.id}" name="group-member"></label>`).join('')||'<p class="hint">请先查找用户。</p>'}</div>`,'<button class="secondary" data-action="close-modal">取消</button><button class="primary" data-action="modal-submit">创建群聊</button>');modalHandler=async()=>{const members=$$('input[name=group-member]:checked').map(x=>x.value);const c=await action('/api/conversations',{kind:'group',name:$('#group-name').value,members});closeModal();await refresh();selectConversation(c.id)}}
function renderContactProfile(){const u=S.profile;$('#main-content').innerHTML=`<header class="chat-head">${btn('back','返回','back','').replace('class="icon-btn"','class="icon-btn mobile-back"')}<h2>个人资料</h2></header><div class="contact-profile">${Contacts.profile(u)}</div>`}
async function showRequests(){modal('联系人通知','<div class="inline-loading">正在读取…</div>','',true);await refresh();$('.modal-body').innerHTML=S.requests.map(q=>`<div class="utility-row">${av(q)}<div class="body"><b>${esc(q.name)}</b><p>${q.sender===S.user.id?'我：':''}${esc(q.message)}</p><p>${shortTime(q.created)}</p></div>${q.status==='pending'&&q.recipient===S.user.id?`<div class="request-actions"><button class="secondary" data-resolve="${q.id}" data-accept="false">拒绝</button><button class="primary" data-resolve="${q.id}" data-accept="true">同意</button></div>`:`<span class="muted">${({pending:'等待验证',accepted:'已添加',rejected:'已拒绝',cancelled:'已取消'})[q.status]}</span>`}</div>`).join('')||'<div class="empty-list">暂无联系人通知</div>'}
async function chatDetail(){if(activeConversation()?.kind==='group'){await Groups.detail();return}const c=await api(`/api/conversations/${S.active}`),mine=c.owner===S.user.id,local=activeConversation();modal('聊天设置',`<div class="detail-members">${c.members.map(u=>`<div class="detail-member">${av(u)}<span>${esc(u.name)}${u.id===c.owner&&c.kind==='group'?' · 群主':''}</span></div>`).join('')}</div>${c.kind==='group'?`<label>群名称</label><input id="detail-name" value="${esc(c.name)}" maxlength="60" ${mine?'':'disabled'}><label>群公告</label><textarea id="detail-notice" maxlength="2000" placeholder="暂无群公告" ${mine?'':'disabled'}>${esc(c.announcement)}</textarea>`:''}<button class="chat-history-entry" data-contact="edit" data-user="${local.peer?.id||''}">好友设置</button><button class="chat-history-entry" data-action="search-history">查找聊天记录</button><label class="prefs-row">置顶聊天<input type="checkbox" id="detail-pin" ${local.pinned?'checked':''}></label><label class="prefs-row">消息免打扰<input type="checkbox" id="detail-mute" ${local.muted?'checked':''}></label>${c.kind==='group'?'<button class="secondary" data-action="invite-members">邀请好友</button>':''}`,`<button class="secondary" data-action="close-modal">取消</button><button class="primary" data-action="modal-submit">保存</button>`);modalHandler=async()=>{const p={pinned:$('#detail-pin').checked,muted:$('#detail-mute').checked};if(c.kind==='group'&&mine){p.name=$('#detail-name').value;p.announcement=$('#detail-notice').value}await api(`/api/conversations/${c.id}`,{method:'PATCH',body:p});closeModal();await refresh();renderMain();toast('已保存')}}
async function inviteMembers(){const cid=S.active,c=await api(`/api/conversations/${cid}`);const list=S.friends.filter(u=>!c.members.some(m=>m.id===u.id));modal('邀请好友入群',`<div class="member-select">${list.map(u=>`<label class="check-row">${av(u)}${esc(u.name)}<input type="checkbox" name="invite-member" value="${u.id}"></label>`).join('')||'<p class="hint">好友都已在群里。</p>'}</div>`,'<button class="primary" data-action="modal-submit">邀请</button>');modalHandler=async()=>{await action(`/api/conversations/${cid}/members`,{members:$$('input[name=invite-member]:checked').map(x=>x.value)});closeModal();toast('已邀请好友入群')}}
function searchHistory(){History.open()}
async function renderFiles(){const n=$('#main-content');n.innerHTML='<section class="utility"><h2>文件管理器</h2><div id="file-list" class="inline-loading">正在读取…</div></section>';try{const files=await api('/api/files'),list=$('#file-list');if(!list)return;list.className='';list.innerHTML=files.map(f=>`<div class="utility-row">${icon(f.mime.startsWith('image/')?'image':'file')}<div class="body"><b>${esc(f.name)}</b><p>${bytes(f.size)} · ${fullTime(f.created)}</p></div>${btn('download','下载','download',`data-download="${f.id}" data-filename="${esc(f.name)}"`)}</div>`).join('')||'<div class="empty-list">发送和接收的文件会保存在这里</div>'}catch(e){toast(e.message)}}
async function renderFavorites(){$('#main-content').innerHTML='<section class="utility"><h2>我的收藏</h2><div id="favorites-list" class="inline-loading">正在读取…</div></section>';try{const items=await api('/api/favorites'),list=$('#favorites-list');if(!list)return;list.className='';list.innerHTML=items.map(m=>`<div class="utility-row">${av(m)}<div class="body"><b>${esc(m.name)}</b><p>${esc(preview(m))}</p><p>${fullTime(m.created)}</p>${m.kind==='voice'||m.kind==='video'?`<div class="favorite-media">${Media.bubble(m)}</div>`:''}${m.kind==='forward'?`<button class="secondary" data-forward-view="${m.id}">查看聊天记录</button>`:''}${m.attachmentId?`<button class="secondary" data-download="${m.attachmentId}" data-filename="${esc(m.fileName)}">下载附件</button>`:''}</div>${btn('trash','取消收藏','unfavorite',`data-mid="${m.id}"`)}</div>`).join('')||'<div class="empty-list">在聊天中长按或右键消息，即可收藏</div>'}catch(e){toast(e.message)}}
function profile(initial={}){const user={...S.user,...initial};modal('编辑资料',`<div style="text-align:center;margin:5px 0 25px"><button class="avatar-edit-button" data-avatar="user" aria-label="更换头像">${av(S.user,'large')}<span class="avatar-edit-hint">更换头像</span></button></div><label>昵称</label><input id="profile-name" value="${esc(user.name)}" maxlength="32"><label>个性签名</label><input id="profile-bio" value="${esc(user.bio)}" maxlength="150" placeholder="分享此刻的心情"><p class="hint">点击头像，从 100 个卡通头像中挑选，或上传自己的照片。</p>`,'<button class="secondary" data-action="close-modal">取消</button><button class="primary" data-action="modal-submit">保存</button>');modalHandler=async()=>{S.user=await api('/api/me',{method:'PATCH',body:{name:$('#profile-name').value,bio:$('#profile-bio').value,avatar:user.avatar}});closeModal();updateRail();if(S.tab==='profile')renderMyPage();toast('个人资料已更新')}}
function renderMyPage(){$('#main-content').innerHTML=`<section class="utility"><div class="settings-body"><div class="contact-profile" style="padding:25px 0">${av(S.user,'large')}<h2>${esc(S.user.name)}</h2><span class="profile-line">WeLink 号：${esc(S.user.number||S.user.account)}</span></div><button class="utility-row" style="width:100%" data-action="profile">${icon('user')}<div class="body" style="text-align:left">个人资料</div>${icon('chevron')}</button><button class="utility-row" style="width:100%" data-nav="drive">${icon('folder')}<div class="body" style="text-align:left">我的网盘</div>${icon('chevron')}</button><button class="utility-row" style="width:100%" data-nav="remote">${icon('monitor')}<div class="body" style="text-align:left">远程协助</div>${icon('chevron')}</button><button class="utility-row" style="width:100%" data-nav="space">${icon('file')}<div class="body" style="text-align:left">我的空间</div>${icon('chevron')}</button>${Admin.settingsRow()}<button class="utility-row" style="width:100%" data-nav="files">${icon('folder')}<div class="body" style="text-align:left">我的文件</div>${icon('chevron')}</button><button class="utility-row" style="width:100%" data-nav="favorites">${icon('star')}<div class="body" style="text-align:left">我的收藏</div>${icon('chevron')}</button>${S.config.platform==='android'?'<button class="utility-row" style="width:100%" data-action="scan-qr"><div class="body" style="text-align:left">扫一扫 · 电脑登录</div></button>':''}<button class="utility-row" style="width:100%" data-action="settings">${icon('settings')}<div class="body" style="text-align:left">设置</div>${icon('chevron')}</button></div></section>`}
function settings(){modal('设置',`<label class="prefs-row">深色外观<input type="checkbox" id="pref-dark" ${document.body.classList.contains('dark')?'checked':''}></label>${Desktop.native?'':'<label class="prefs-row">桌面消息通知<button class="secondary" data-action="notifications">开启通知</button></label>'}${Desktop.settingsRow()}${Outbox.settingsRow()}${Received.settingsRow()}${Admin.settingsRow()}<div class="prefs-row"><span>账号与安全</span><button class="secondary" data-action="security">管理</button></div><div class="prefs-row"><span>联系人与隐私</span><button class="secondary" data-contact="privacy">管理</button></div><div class="prefs-row"><span>当前版本</span><span>0.1.0 预览版</span></div><div class="prefs-row"><span>服务器</span><span>${esc(S.config.server||'本地')}</span></div><p class="hint">聊天记录保存在服务器，登录同一账号即可同步。<br>远程协助每次都需要对方明确同意。</p><button class="secondary" data-action="connection">连接设置</button> <button class="secondary" data-action="licenses">开源许可</button>`,`<button class="secondary danger" data-action="logout">退出登录</button><button class="primary" data-action="modal-submit">完成</button>`);modalHandler=async()=>{document.body.classList.toggle('dark',$('#pref-dark').checked);localStorage.setItem('welink_dark',String($('#pref-dark').checked));closeModal()}}
function connection(){modal('连接设置',`<label>服务地址</label><input id="server-url" value="${esc(S.config.server||'')}" placeholder="http://服务器:8250"><label>HTTPS 证书指纹（可选）</label><input id="server-pin" value="${esc(S.config.fingerprint||'')}" placeholder="64 位十六进制指纹"><p class="hint">当前默认使用 HTTP。证书指纹仅在使用 HTTPS 时生效。</p>`,'<button class="secondary" data-action="close-modal">取消</button><button class="primary" data-action="modal-submit">保存连接</button>');modalHandler=async()=>{const cfg=await action('/local/config',{server:$('#server-url').value,fingerprint:$('#server-pin').value});S.config=cfg;closeModal();await logout(false);toast('连接已更新，请登录')}}
function contextMenu(x,y,items){$('.context-menu')?.remove();const n=document.createElement('div');n.className='context-menu';n.innerHTML=items;document.body.append(n);const r=n.getBoundingClientRect();n.style.left=Math.max(8,Math.min(x,innerWidth-r.width-8))+'px';n.style.top=Math.max(8,Math.min(y,innerHeight-r.height-8))+'px'}
function messageMenu(m,x,y){contextMenu(x,y,(m.recalled?'':`${Mentions.menu(m)}<button data-action="quote" data-mid="${m.id}">${icon('reply')}引用</button><button data-fw="single" data-mid="${m.id}">${icon('send')}转发</button>${m.kind==='text'?`<button data-action="copy-message" data-mid="${m.id}">${icon('copy')}复制文字</button>`:''}<button data-action="favorite" data-mid="${m.id}">${icon('star')}收藏</button>${m.sender===S.user.id&&Date.now()-m.created<120000?`<button data-action="recall" data-mid="${m.id}">${icon('history')}撤回</button>`:''}`)+`<button data-fw="select" data-mid="${m.id}">${icon('check')}多选</button><button class="destructive" data-action="delete-message" data-mid="${m.id}">${icon('trash')}删除</button>`)}
function emojis(){const old=$('.popup');if(old){old.remove();return};const d=document.createElement('div');d.className='popup';d.innerHTML=[...'😀😃😄😁😆😅😂🙂😉😊🥰😍🤩😘😋😎🥳🤔🤗🤭🤫😴😪😮😯😳😱😢😭😤😡🤯🥺😇💙❤️💛💚💜✨🌟🎉🎈🎁🌷🌸🍀☀️🌈☕🍰🍉🍎🎵💡🔥👍👋👏🤝🙏💪👌✅'].map(v=>`<button data-emoji="${v}">${v}</button>`).join('');$('.composer').append(d)}

async function copyMessage(text){if(navigator.clipboard?.writeText){await navigator.clipboard.writeText(text)}else{const input=document.createElement('textarea');input.value=text;input.style.position='fixed';input.style.opacity='0';document.body.append(input);input.select();const copied=document.execCommand('copy');input.remove();if(!copied)throw Error('复制失败，请重试')}toast('已复制')}
function applyRecall(message){Received.event('recall',message).catch(()=>{});Mentions.invalidated(message.id);Media.invalidate(message.id);Forwarding.invalidate(message.id);const i=S.messages.findIndex(m=>m.id===message.id);if(i>=0)S.messages[i]=message;for(const m of S.messages)if(m.reply?.id===message.id)m.reply={...m.reply,text:'',fileName:'',recalled:true};if(S.reply?.id===message.id){S.reply=null;renderReply()}History.changed(message.id,true);renderMessages(true);queueRefresh()}
function applyDeletion(message){Received.event('message-deleted',message).catch(()=>{});Mentions.invalidated(message.id);Media.invalidate(message.id);Forwarding.removed(message.id);if(S.active===message.conversationId){S.messages=S.messages.filter(m=>m.id!==message.id);if(S.reply?.id===message.id){S.reply=null;renderReply()}renderMessages(true)}History.changed(message.id);queueRefresh()}
function deleteMessage(id){const cid=S.active;modal('删除消息','<p class="hint">删除后，这条消息将从你所有设备的聊天记录中移除。对方的记录和你已保存的收藏会保留。</p>','<button class="secondary" data-action="close-modal">取消</button><button class="primary" data-action="modal-submit">删除</button>');modalHandler=async()=>{await api('/api/messages/'+id,{method:'DELETE'});applyDeletion({id,conversationId:cid});closeModal();toast('已删除消息')}}
async function jumpMessage(cid,id){const current=S.messages.find(m=>m.id===id);if(S.active!==cid||!current){const messages=await api('/api/conversations/'+cid+'/messages?around='+encodeURIComponent(id));S.active=cid;S.messages=messages;S.historyMode=true;S.tab='messages';S.profile=null;S.reply=Outbox.replyPlaceholder(cid);renderShell();Outbox.restoreReply(cid).catch(()=>{})}closeModal();const target=document.querySelector('[data-message="'+id+'"]');if(!target)throw Error('消息已删除或不可访问');target.scrollIntoView({block:'center',behavior:'auto'});target.classList.remove('highlight-message');void target.offsetWidth;target.classList.add('highlight-message')}

async function screenshot(){if(!navigator.mediaDevices?.getDisplayMedia){toast('此设备请使用系统截图后发送图片');return}let stream;try{stream=await navigator.mediaDevices.getDisplayMedia({video:true,audio:false});const video=document.createElement('video');video.srcObject=stream;await video.play();await new Promise(r=>setTimeout(r,150));const canvas=document.createElement('canvas');canvas.width=video.videoWidth;canvas.height=video.videoHeight;canvas.getContext('2d').drawImage(video,0,0);stream.getTracks().forEach(t=>t.stop());canvas.toBlob(b=>{if(b)upload(new File([b],'截图-'+Date.now()+'.png',{type:'image/png'}))},'image/png')}catch(e){if(e.name!=='NotAllowedError')toast('截图失败：'+e.message)}finally{stream?.getTracks().forEach(t=>t.stop())}}
function renderRemoteHome(){$('#main-content').innerHTML=`<section class="utility"><h2>远程协助</h2><div class="settings-body"><div style="text-align:center;padding:28px 0;color:#80bced">${icon('monitor').replace('<svg','<svg style="width:72px;height:72px;stroke-width:1"')}</div><h3 style="text-align:center;font-weight:500;font-size:20px;margin-bottom:14px">屏幕另一边，也能帮到你</h3><p class="hint" style="text-align:center;color:#99a3b0;line-height:2;font-size:13px;margin-bottom:35px">在好友聊天中发起远程协助<br>共享屏幕，或邀请好友操作你的设备</p><div class="utility-row">${icon('shield')}<div class="body"><b>每次连接，都由你决定</b><p>对方同意后才开始，随时可以结束</p></div></div><div class="utility-row">${icon('monitor')}<div class="body"><b>Windows 与 Android 互联</b><p>复用 YuDesk 远控技术，支持加密传输</p></div></div><button class="primary" style="width:100%;margin-top:20px" data-nav="contacts">选择好友</button></div></section>`}
function remoteChoices(){const c=activeConversation();if(c?.kind!=='direct'){toast('请在好友单聊中使用远程协助');return}modal('远程协助',`<button class="remote-choice" data-invite-remote="control" data-direction="request">${icon('monitor')}<span><b>请求控制对方设备</b><p>对方同意后，帮助对方操作</p></span></button><button class="remote-choice" data-invite-remote="view" data-direction="request">${icon('video')}<span><b>请求观看对方屏幕</b><p>只看画面，不操作对方设备</p></span></button><button class="remote-choice" data-invite-remote="control" data-direction="share">${icon('contacts')}<span><b>邀请对方协助我</b><p>共享我的屏幕，允许对方操作</p></span></button><p class="hint">邀请在 60 秒后失效。安卓共享需要系统屏幕录制授权，触控需要无障碍权限。</p>`)}
async function ensureSharing(){if(S.config.platform==='android'){if(!window.WeLinkAndroid)throw Error('当前环境不支持 Android 屏幕共享');window.WeLinkAndroid.requestSharing();const deadline=Date.now()+60000;while(Date.now()<deadline){await new Promise(r=>setTimeout(r,500));const s=await api('/local/remote/state');if(s.sharing)return s}throw Error('屏幕共享未获授权')}return api('/local/remote/state')}
async function inviteRemote(mode,direction){const local=direction==='share'?await ensureSharing():await api('/local/remote/state');const v=await action('/api/remotes',{conversationId:S.active,mode,direction,deviceId:local.deviceId});S.remote=v;closeModal();renderRemoteWait(v)}
function renderRemoteWait(v){modal('远程协助',`<div class="remote-invite">${av(activeConversation()?.peer||{},'large')}<h3>等待对方接受邀请…</h3><p>邀请将在 60 秒后自动失效<br>你可以随时取消</p></div>`,'<button class="secondary" data-action="stop-remote">取消邀请</button>');clearTimeout(toastTimer);toastTimer=setTimeout(async()=>{if(S.remote?.id===v.id&&S.remote.state==='pending'){await stopRemote();toast('对方未响应，邀请已过期')}},60000)}
async function remoteEvent(v){if(!S.user)return;if(v.state==='pending'){if(v.requester===S.user.id)return;S.remote=v;const from=S.friends.find(u=>u.id===v.requester)||{name:'好友'};modal('远程协助邀请',`<div class="remote-invite">${av(from,'large')}<h3>${esc(from.name)}</h3><p>${v.host===S.user.id?(v.mode==='control'?'请求观看并控制你的设备':'请求观看你的屏幕'):'邀请你远程协助'}<br>同意后开始，随时可以结束</p></div>`,'<button class="secondary" data-action="reject-remote">拒绝</button><button class="primary" data-action="accept-remote">同意</button>');return};if(S.remote?.id!==v.id)return;S.remote=v;if(v.state==='accepted'){clearTimeout(toastTimer);if(v.host!==S.user.id||v.requester===S.user.id)try{await startRemote(v)}catch(e){toast(e.message);await stopRemote()}}else{await stopRemote(false);if(v.state==='rejected')toast('对方拒绝了远程邀请');else toast('远程协助已结束')}}
async function acceptRemote(accept){const v=S.remote;if(!v)return;let local;if(accept&&v.host===S.user.id)local=await ensureSharing();const result=await action(`/api/remotes/${v.id}/respond`,{accept,deviceId:local?.deviceId||''});S.remote=result;closeModal();if(accept)await startRemote(result);else S.remote=null}
async function startRemote(v){await action('/local/remote/start',{id:v.id,token:S.token});closeModal();S.remote=v;clearInterval(S.remoteTimer);if(v.host!==S.user.id)showRemoteScreen();else renderSharing();S.remoteTimer=setInterval(remoteTick,120);await remoteTick()}
let frameVersion=0,frameURL='',remoteTickBusy=false,inputChain=Promise.resolve();
async function remoteTick(){if(remoteTickBusy||!S.remote)return;remoteTickBusy=true;try{const state=await api('/local/remote/state');S.remoteLocal=state;const status=$('#remote-status');if(status)status.textContent=state.status==='connected'?`${state.path==='p2p'?'P2P 直连':'加密中转'} · ${state.rtt} ms · ${state.width}×${state.height}`:state.error||'正在建立加密连接…';if(state.status==='ended'){const error=state.error;await stopRemote();if(error)toast(error);return}if(state.role==='viewer'&&state.frame!==frameVersion&&state.frame){frameVersion=state.frame;const r=await fetch('/local/remote/frame');if(r.ok){const blob=await r.blob();const img=$('#remote-image');if(img){const old=frameURL;frameURL=URL.createObjectURL(blob);img.src=frameURL;img.onload=()=>{URL.revokeObjectURL(old);$('#remote-loading')?.classList.add('hidden')};img.dataset.width=state.width;img.dataset.height=state.height}}}}catch(e){toast(e.message);await stopRemote(false)}finally{remoteTickBusy=false}}
function renderSharing(){const el=$('#sharing-banner');if(!el)return;el.innerHTML=S.remote?.state==='accepted'&&S.remote.host===S.user.id?`<div class="sharing-banner">${icon('monitor')}<span>正在共享屏幕${S.remote.mode==='control'?'，对方可以操作':''}</span><button data-action="stop-remote">结束共享</button></div>`:''}
function showRemoteScreen(){if($('.remote-screen'))return;const node=document.createElement('section');node.className='remote-screen';node.innerHTML=`<header class="remote-toolbar">${icon('monitor')}<b>远程协助</b><span id="remote-status" class="status">正在连接…</span><button class="secondary" data-action="remote-fullscreen">全屏</button><button class="primary" data-action="stop-remote">结束协助</button></header><div class="remote-canvas"><p id="remote-loading">正在等待对方画面…</p><img id="remote-image" tabindex="0" alt="远程设备屏幕"></div><div class="remote-touchbar"><button data-remote-key="Escape">返回</button><button data-remote-key="Home">主页</button><button data-action="remote-text">输入文字</button><button data-remote-key="Enter">回车</button></div>`;document.body.append(node);const img=$('#remote-image');let held=false;const send=events=>{inputChain=inputChain.then(()=>action('/local/remote/input',{events})).catch(e=>toast(e.message))};const point=e=>{const r=img.getBoundingClientRect();return {type:'move',x:Math.max(0,Math.round((e.clientX-r.left)*Number(img.dataset.width)/r.width)),y:Math.max(0,Math.round((e.clientY-r.top)*Number(img.dataset.height)/r.height))}};let moveAt=0;img.onpointerdown=e=>{if(S.remote?.mode!=='control')return;e.preventDefault();img.focus();img.setPointerCapture(e.pointerId);held=true;send([point(e),{type:'down',button:e.button===2?3:1}])};img.onpointermove=e=>{if(S.remote?.mode!=='control'||Date.now()-moveAt<35)return;moveAt=Date.now();send([point(e)])};img.onpointerup=e=>{if(!held)return;held=false;send([point(e),{type:'up',button:e.button===2?3:1}])};img.onpointercancel=()=>{held=false;action('/local/remote/release').catch(()=>{})};img.oncontextmenu=e=>e.preventDefault();img.onwheel=e=>{if(S.remote?.mode!=='control')return;e.preventDefault();send([{type:'wheel',deltaY:Math.round(e.deltaY),deltaX:Math.round(e.deltaX)}])};img.onkeydown=e=>{if(S.remote?.mode!=='control')return;e.preventDefault();send([{type:'key_down',key:e.key,code:e.code}])};img.onkeyup=e=>{if(S.remote?.mode!=='control')return;e.preventDefault();send([{type:'key_up',key:e.key,code:e.code}])};img.onblur=()=>action('/local/remote/release').catch(()=>{})}
async function stopRemote(notify=true){const v=S.remote;S.remote=null;S.remoteLocal=null;clearInterval(S.remoteTimer);clearTimeout(toastTimer);S.remoteTimer=null;$('.remote-screen')?.remove();frameVersion=0;URL.revokeObjectURL(frameURL);frameURL='';closeModal();renderSharing();try{await action('/local/remote/stop')}catch{}if(notify&&v)try{await action(`/api/remotes/${v.id}/end`)}catch{}}
async function download(id,name){if(window.WeLinkAndroid){window.WeLinkAndroid.downloadFile(fileURL(id),name||'文件');return}const a=document.createElement('a');a.href=fileURL(id);a.download=name||'文件';document.body.append(a);a.click();a.remove()}
document.addEventListener('click',async e=>{const b=e.target.closest('button,a,[data-preview-image]');$('.context-menu')?.remove();if(!b)return;try{if(b.dataset.nav){closeModal();S.tab=b.dataset.nav;if(S.tab==='space')S.spaceUser='me';S.search='';S.profile=null;renderShell();return}if(b.dataset.contactTab){S.contactTab=b.dataset.contactTab;renderSidebar();return}if(b.dataset.conversation){await selectConversation(b.dataset.conversation);return}if(b.dataset.profile){S.profile=S.friends.find(u=>u.id===b.dataset.profile);renderMain();$('.shell').classList.add('in-chat');return}if(b.dataset.userCall){closeModal();const c=await action('/api/conversations',{kind:'direct',members:[b.dataset.userCall]});await refresh();await selectConversation(c.id);await Calls.dial(c.id,b.dataset.userCallMode==='video'?'video':'audio');return}if(b.dataset.startChat){const c=await action('/api/conversations',{kind:'direct',members:[b.dataset.startChat]});await refresh();await selectConversation(c.id);return}if(b.dataset.requestUser){requestFriend(b.dataset.requestUser,b.dataset.name);return}if(b.dataset.resolve){await action('/api/requests/'+b.dataset.resolve,{accept:b.dataset.accept==='true'});await showRequests();return}if(b.dataset.color){$$('.color-list button').forEach(x=>x.classList.toggle('selected',x===b));return}if(b.dataset.emoji){const input=$('#composer');const start=input.selectionStart;input.value=input.value.slice(0,start)+b.dataset.emoji+input.value.slice(input.selectionEnd);input.dispatchEvent(new Event('input'));input.focus();input.setSelectionRange(start+b.dataset.emoji.length,start+b.dataset.emoji.length);return}if(b.dataset.inviteRemote){await inviteRemote(b.dataset.inviteRemote,b.dataset.direction);return}if(b.dataset.remoteKey){await action('/local/remote/input',{events:[{type:'key',key:b.dataset.remoteKey}]});return}if(b.dataset.download){await download(b.dataset.download,b.dataset.filename);return}if(b.dataset.previewImage){$('#overlays').innerHTML=`<div class="modal-backdrop" data-action="close-modal"><img class="image-preview" src="${fileURL(b.dataset.previewImage)}" alt="图片预览"></div>`;return}const a=b.dataset.action;if(!a)return;$('.context-menu')?.remove();switch(a){case 'register':renderAuth(true);break;case 'login':renderAuth(false);break;case 'close-modal':closeModal();break;case 'modal-submit':if(modalHandler){b.disabled=true;try{await modalHandler()}finally{b.disabled=false}}break;case 'window-min':case 'window-max':case 'window-close':await action('/local/window/'+a.slice(7));break;case 'connection':connection();break;case 'licenses':{const text=await (await fetch('/assets/licenses.txt')).text();modal('开源许可','<pre class="license-text">'+esc(text)+'</pre>','',true);break;}case 'profile':profile();break;case 'settings':settings();break;case 'logout':await logout();break;case 'send':await sendMessage();break;case 'back':S.active=null;S.profile=null;renderShell();break;case 'add-friend':addFriend();break;case 'create-group':createGroup();break;case 'requests':await showRequests();break;case 'add-menu':{const r=b.getBoundingClientRect();contextMenu(r.left-120,r.bottom+5,`<button data-action="add-friend">${icon('contacts')}查找用户</button><button data-group="search">${icon('search')}查找群聊</button><button data-action="create-group">${icon('chat')}创建群聊</button>${S.config.platform==='android'?'<button data-action="scan-qr">扫一扫</button>':''}`);break}case 'more-menu':{const r=b.getBoundingClientRect();contextMenu(r.left+40,r.top-80,`<button data-action="settings">${icon('settings')}设置</button><button data-action="logout">${icon('logout')}退出登录</button>${Desktop.exitMenu()}`);break}case 'emoji':emojis();break;case 'image':$('#image-input').click();break;case 'file':$('#file-input').click();break;case 'screenshot':await screenshot();break;case 'search-history':searchHistory();break;case 'chat-detail':await chatDetail();break;case 'invite-members':await inviteMembers();break;case 'quote':S.reply=S.messages.find(m=>m.id===b.dataset.mid);Outbox.saveDraft().catch(()=>{});renderReply();$('#composer')?.focus();break;case 'cancel-reply':S.reply=null;Outbox.saveDraft().catch(()=>{});renderReply();break;case 'favorite':await action('/api/favorites/'+b.dataset.mid);toast('已收藏');break;case 'unfavorite':await api('/api/favorites/'+b.dataset.mid,{method:'DELETE'});await renderFavorites();break;case 'copy-message':await copyMessage(S.messages.find(m=>m.id===b.dataset.mid)?.text||'');break;case 'delete-message':deleteMessage(b.dataset.mid);break;case 'jump-message':await jumpMessage(S.active,b.dataset.mid);break;case 'latest-messages':await selectConversation(S.active);break;case 'load-newer':{const cid=S.active,area=$('#messages'),top=area.scrollTop;const ms=await api(`/api/conversations/${cid}/messages?after=${S.messages[S.messages.length-1].seq}`);if(S.active!==cid)break;if(!ms.length){toast(S.cacheView?'已到本机缓存的最新消息':'已到最新消息');S.historyMode=false}else S.messages.push(...ms.filter(m=>!S.messages.some(x=>x.id===m.id)));renderMessages(true);area.scrollTop=top;break}case 'recall':{const m=await action('/api/messages/'+b.dataset.mid+'/recall');applyRecall(m);break}case 'load-older':{const cid=S.active,seq=S.messages[0]?.seq;if(!cid||!seq)break;const older=await api(`/api/conversations/${cid}/messages?before=${seq}`);if(S.active!==cid||S.messages[0]?.seq!==seq)break;if(!older.length){b.remove();toast(S.cacheView?'没有更早的本机缓存，联网后可继续加载':'已经是最早的消息');break}const area=$('#messages'),h=area.scrollHeight;S.messages=[...older,...S.messages];renderMessages(true);area.scrollTop=area.scrollHeight-h;break}case 'notifications':if(window.WeLinkAndroid){window.WeLinkAndroid.requestNotifications();break}if('Notification'in window){const p=await Notification.requestPermission();toast(p==='granted'?'已开启桌面通知':'通知权限未开启')}break;case 'remote':remoteChoices();break;case 'accept-remote':b.disabled=true;await acceptRemote(true);break;case 'reject-remote':await acceptRemote(false);break;case 'stop-remote':await stopRemote();break;case 'remote-fullscreen':if(!document.fullscreenElement)await $('.remote-screen').requestFullscreen();else await document.exitFullscreen();break;case 'remote-text':modal('输入文字','<textarea id="remote-text" placeholder="输入要发送到远程设备的文字"></textarea>','<button class="primary" data-action="modal-submit">发送</button>');modalHandler=async()=>{await action('/local/remote/input',{events:[{type:'text',text:$('#remote-text').value}]});closeModal()};break}}catch(err){modalError(err)}});
document.addEventListener('click',e=>{if(e.target.classList.contains('modal-backdrop')&&!S.remote)closeModal()});
document.addEventListener('contextmenu',e=>{const el=e.target.closest('[data-message]');if(el){e.preventDefault();const m=S.messages.find(x=>x.id===el.dataset.message);if(m)messageMenu(m,e.clientX,e.clientY)}});
let touchTimer,suppressMessageClickUntil=0;document.addEventListener('click',e=>{if(Date.now()<suppressMessageClickUntil&&e.target.closest('[data-message]')){e.preventDefault();e.stopImmediatePropagation()}},true);document.addEventListener('touchstart',e=>{const el=e.target.closest('[data-message]');if(el){const p=e.touches[0];touchTimer=setTimeout(()=>{const m=S.messages.find(x=>x.id===el.dataset.message);if(m){suppressMessageClickUntil=Date.now()+1000;messageMenu(m,p.clientX,p.clientY)}},550)}},{passive:true});for(const ev of ['touchend','touchmove','touchcancel'])document.addEventListener(ev,()=>clearTimeout(touchTimer),{passive:true});
document.addEventListener('visibilitychange',()=>{if(!Desktop.hidden()){document.title='WeLink';if(S.active&&S.user)markRead().catch(()=>{})}else action('/local/remote/release').catch(()=>{})});
document.addEventListener('pointerdown',e=>{if(e.button===0&&window.welinkDrag&&!e.target.closest('button,input,textarea,a')&&(e.target.closest('.chat-head')||e.clientY<28))window.welinkDrag()});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if($('.context-menu'))$('.context-menu').remove();else if(!S.remote)closeModal();$('.popup')?.remove()}});
window.addEventListener('storage',event=>{if((event.key==='welink_token'||event.key===null)&&S.token&&localStorage.getItem('welink_token')!==S.token)logout(false)});
if(localStorage.getItem('welink_dark')==='true')document.body.classList.add('dark');
const Received=createReceivedCache({S,toast,modal,closeModal,esc,bytes,connectionState,onReconciled:(cid,messages,ids,denied)=>{
 if(S.active!==cid)return;
 const live=new Map(messages.map(m=>[m.id,m])),checked=new Set(ids);
 // Cache limits must not remove uncached rows already loaded in online history.
 S.messages=denied?[]:S.messages.filter(m=>!checked.has(m.id)||live.has(m.id)).map(m=>live.get(m.id)||m);
 if(S.reply&&(denied||checked.has(S.reply.id)&&(!live.has(S.reply.id)||live.get(S.reply.id).recalled))){S.reply=null;renderReply()}
 renderMessages(true);
}});
