async function bootstrap(){try{S.config=await api('/local/config');S.registrationEnabled=(await api('/api/public-config')).registrationEnabled;if(S.token){try{S.user=await api('/api/me');await enter()}catch(error){if(error.status===401){S.token='';localStorage.removeItem('welink_token');renderAuth()}else throw error}}else renderAuth()}catch(error){Outbox.stop();S.user=null;$('#app').innerHTML='<main class="auth-shell">'+windows()+'<section class="auth-card">'+logo()+'<h2>正在重新连接</h2><p class="subtitle">登录状态与本机草稿已保留</p><p class="auth-error">'+esc(error.message)+'</p><button class="primary" id="retry-connect">立即重试</button><div class="auth-links"><button data-action="logout">返回登录</button><button data-action="connection">连接设置</button></div></section></main>';$('#retry-connect').onclick=bootstrap;setTimeout(()=>{if($('#retry-connect'))bootstrap()},10000)}}
bootstrap();

let fileDragDepth=0;const fileDrag=e=>Array.from(e.dataTransfer?.types||[]).includes('Files');document.addEventListener('dragenter',e=>{if(!fileDrag(e)||!S.user)return;e.preventDefault();if(S.tab==='drive'||S.tab==='messages'&&S.active){fileDragDepth++;document.querySelector('.shell')?.classList.add('file-drop-active')}});document.addEventListener('dragover',e=>{if(fileDrag(e)){e.preventDefault();if(e.dataTransfer)e.dataTransfer.dropEffect='copy'}});document.addEventListener('dragleave',e=>{if(fileDrag(e)&&--fileDragDepth<=0)document.querySelector('.shell')?.classList.remove('file-drop-active')});document.addEventListener('drop',async e=>{if(!fileDrag(e))return;e.preventDefault();fileDragDepth=0;document.querySelector('.shell')?.classList.remove('file-drop-active');const files=Array.from(e.dataTransfer.files||[]),cid=S.active,owner=S.token;if(!S.user)return;if(S.tab==='drive'){await Cloud.sendFiles(files);return}if(S.tab!=='messages'||!cid){toast('请先打开聊天或网盘');return}for(const file of files){if(S.token!==owner)return;await upload(file,false,cid)}});
